<script setup lang="ts">import{ref}from'vue';import{createDeploymentPlan}from'./api';const manifestText=ref(''),reason=ref(''),result=ref<Record<string,unknown>|null>(null),error=ref('');async function createPlan(){try{const manifest=JSON.parse(manifestText.value);if(!reason.value.trim())throw new Error('사유 필수');result.value=await createDeploymentPlan({manifest,requestedBy:'authenticated-operator',reason:reason.value})}catch(e){error.value=String(e)}}</script>
<template><section><h1>Deployment / Rollback</h1><p>Plan 생성 후 기존 ADM Approval에서 BAT / DEPLOY_PLAN 또는 ROLLBACK_PLAN을 승인합니다.</p><textarea v-model="manifestText" rows="18"/><input v-model="reason" placeholder="사유"/><button @click="createPlan">Plan 생성</button><p v-if="error" role="alert">{{error}}</p><pre v-if="result">{{JSON.stringify(result,null,2)}}</pre></section></template>
